// Security headers for every response produced by the SSR function (all HTML pages).
//
// Why this lives in code: Netlify's `_headers` file and `[[headers]]` in netlify.toml are applied
// ONLY to static files. Responses generated by a function / SSR handler never get them
// (https://docs.netlify.com/manage/routing/headers/ → "Limitations"), so the headers have to be
// attached here. Static files (images, PDFs) get their headers from netlify.toml.

const CSP_DIRECTIVES = [
  "default-src 'self'",
  // TanStack Start streams inline bootstrap/hydration scripts and we ship JSON-LD, so inline scripts
  // must be allowed. Everything else is restricted to our own origin: injected <script src> from other
  // hosts, plugins (object-src), base-tag hijacking and framing by other sites are all blocked.
  "script-src 'self' 'unsafe-inline'",
  "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
  "font-src 'self' data: https://fonts.gstatic.com",
  "img-src 'self' data: blob:",
  "connect-src 'self'",
  "frame-src 'self'",
  "manifest-src 'self'",
  "object-src 'none'",
  "base-uri 'self'",
  "form-action 'self'",
  "frame-ancestors 'self'",
  "upgrade-insecure-requests",
];

export const CONTENT_SECURITY_POLICY = CSP_DIRECTIVES.join("; ");

export const SECURITY_HEADERS: Readonly<Record<string, string>> = {
  "X-Content-Type-Options": "nosniff",
  "X-Frame-Options": "SAMEORIGIN",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "Permissions-Policy":
    "camera=(), microphone=(), geolocation=(), payment=(), usb=(), interest-cohort=()",
  "Cross-Origin-Opener-Policy": "same-origin",
  // No includeSubDomains / preload on purpose: those are hard to undo if a subdomain (for example a
  // mail or staging host) is ever served over plain HTTP.
  "Strict-Transport-Security": "max-age=31536000",
};

type EnvHolder = { process?: { env?: Record<string, string | undefined> } };

function cspHeaderName(): string {
  // Escape hatch: set CSP_REPORT_ONLY=1 in Netlify to log violations instead of blocking, without a
  // code change, if a future feature trips the policy.
  const env = (globalThis as EnvHolder).process?.env;
  return env?.["CSP_REPORT_ONLY"] === "1"
    ? "Content-Security-Policy-Report-Only"
    : "Content-Security-Policy";
}

// Pages are identical for every visitor (no cookies, no sessions), so the Netlify CDN may cache
// successful HTML for a few minutes. This cuts function invocations (cost and abuse surface) and
// improves response time for crawlers. Each new deploy purges the CDN cache automatically.
function cacheHeaders(request: Request, response: Response, headers: Headers): void {
  const isHtml = (response.headers.get("content-type") ?? "").includes("text/html");
  const readOnly = request.method === "GET" || request.method === "HEAD";
  if (isHtml && readOnly && response.status === 200 && !headers.has("netlify-cdn-cache-control")) {
    headers.set("Cache-Control", "public, max-age=0, must-revalidate");
    headers.set("Netlify-CDN-Cache-Control", "public, s-maxage=300, stale-while-revalidate=3600");
  }
}

export function withSecurityHeaders(response: Response, request?: Request): Response {
  const headers = new Headers(response.headers);
  for (const [name, value] of Object.entries(SECURITY_HEADERS)) {
    if (!headers.has(name)) headers.set(name, value);
  }
  const cspName = cspHeaderName();
  if (!headers.has(cspName)) headers.set(cspName, CONTENT_SECURITY_POLICY);
  if (request) cacheHeaders(request, response, headers);
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}
